 GovernanceWorkChargeSource result;result.id=take(c.next_id("governance_work_charge"));result.charge_key=value.key;result.expense_terms_ref=r;result.work_id=t.work_id;result.trigger_evidence=evidence;result.earned_at=value.measured.occurred_at;result.measured_quantity=value.measured.actual_quantity;result.earned_qian=value.earned;
 if(result.earned_qian){result.original_obligation_id=take(c.next_id("governance_work_obligation"));result.original_arrear_id=take(c.next_id("contract_payment_due"));}
