Outcome<OriginalEconomicPayable>read_original_work_charge_for_obligation(const GovernanceWorkExpenseReadContext&x,const MomentOwnerSource&r){try{
 if(r.source_schema!=1||r.source_ref.domain!="local_economy"||r.source_ref.kind!="governance_work_charge")fail("UnsupportedOriginalWorkPayableSource",r.source_ref.id);
 const auto*q=x.state.charges.find(r.source_ref.id);if(!q||q->id!=r.source_ref.id||q->earned_qian<=0||q->original_obligation_id.empty()||q->original_arrear_id.empty())fail("OriginalWorkPayableChargeRequired",r.source_ref.id);
 header(x.common,r.source_ref);const auto&t=lookup(x,q->expense_terms_ref);const auto&l=line(t.frozen,q->charge_key.line_id);const auto actual=evaluate(x,t,l,q->trigger_evidence,q->id);
 if(!actual.measured.qualifies||!same_key(actual.key,q->charge_key)||actual.earned!=q->earned_qian||cmp(actual.measured.occurred_at,q->earned_at)||cmp(actual.measured.actual_quantity,q->measured_quantity))fail("OriginalWorkPayableEarnedSourceMismatch",q->id);
 for(const auto&v:x.state.charges.rows())if(v.first!=q->id&&(same_key(v.second.charge_key,q->charge_key)||v.second.original_obligation_id==q->original_obligation_id||v.second.original_arrear_id==q->original_arrear_id))fail("DuplicateOriginalWorkPayableSource",q->id);
 return {true,{{"local_economy",q->original_obligation_id},{"local_economy","contract_payment_due",q->original_arrear_id},r,q->earned_at,q->earned_at,q->earned_qian},{}};
}catch(const Failure&e){return {false,{},e.error};}}
